// kaya runtime for C# guests: loading, the direct-ring occurrence loop,
// and submit. Hand-written; the wire vocabulary next to it
// (KayaWire.cs) is generated by kaya-bindgen.
//
// The direct tier: C# reads the occurrence ring with Volatile loads and
// stores — P/Invoke is crossed only to start the core, to wait on an
// empty ring, and to submit. The consumer contract is the io_uring
// recipe documented in kaya.h.

using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;
using System.Text;
using System.Threading;

/// One file the picker answered with: a handle to redeem, a display
/// name, and LocalPath — a RE-OPENABLE NAME, empty unless re-opening it
/// actually works, which measurement puts at the three desktops and
/// neither phone (DESIGN.md, File dialogs).
public readonly record struct PickedFile(ulong Handle, string Name, string LocalPath)
{
    /// Redeem the handle for a real FileStream, plus whether it seeks.
    ///
    /// BLOCKS, and may block for a long time, so call it from a thread
    /// you chose and post the result back. kaya is not in the data
    /// path: the stream returned is a real file.
    ///
    /// Seekable RIDES THE OPEN rather than the pick because that is the
    /// only place the answer exists — an Android provider may hand back
    /// a pipe, and nothing short of opening reveals it.
    public (FileStream File, bool Seekable) Open(uint mode = 0)
        => Kaya.OpenPicked(Handle, mode);
}

/// One open asset: the bytes of a file the app's own BUILD shipped,
/// held by the core and named the same way on five platforms
/// (docs/assets-plan.md, ratified 2026-08-18). Tx.Asset opens one.
///
///     using var font = tx.Asset("fonts/sora-wght.ttf");
///     tx.BrandTypeface("Sora", font);
///
/// WHERE that name resolves is the core's knowledge and never the app's:
/// a directory in a repo checkout, a .app bundle's Resources, an APK's
/// packaged assets/, which is not a directory and has no path at all.
/// Before this existed the rule was hand-written once per guest
/// language — eight environment-variable reads, eight repo-relative
/// defaults, eight sentences for one failure.
///
/// TWO REDEMPTIONS, and the first is the interesting one:
///
///  - HAND IT TO KAYA. The BrandTypeface and AppIdentity overloads that
///    take an Asset, where the bytes never enter .NET: the core clones a
///    refcount into the blob table the wire already has.
///  - READ IT YOURSELF. Bytes() copies them out and Open() wraps that
///    copy in a MemoryStream.
///
/// FILE-LIKE READING IS THIS BINDING'S SUGAR, with zero core surface:
/// Open() is a MemoryStream the way Python's is a BytesIO and Go's a
/// bytes.Reader. THERE IS NO FILE HANDLE anywhere on the asset surface —
/// a handle was PickedFile's necessity, because a provider-opened file
/// has no path behind it, and kaya resolved this name and produced these
/// bytes itself. Read-only structurally, too: no call here takes a mode,
/// so the FileAccess this file picks for a picked file has no sibling
/// here to disagree with.
///
/// DISPOSING. Dispose releases the core's handle, `using` disposes on
/// the way out, and the finalizer releases one a guest forgot — so a
/// guest that never disposes leaks nothing, and one that disposes twice
/// pays nothing (the core's release is idempotent).
public sealed class Asset : IDisposable
{
    ulong handle;

    internal Asset(ulong handle, string name)
    {
        this.handle = handle;
        Name = name;
    }

    /// The name this asset was asked for — what Tx.Asset was given, not
    /// a path. There is no path to hand back on Android at all, so none
    /// of the nine bindings offers one.
    public string Name { get; }

    /// The asset's bytes, copied out of core memory.
    ///
    /// A METHOD RATHER THAN A PROPERTY, deliberately: a property is a
    /// promise that reading it is cheap, and this one allocates and
    /// copies the whole file every time it is called (a hundred
    /// kilobytes, for the font this surface was written for). That is
    /// what MemoryStream.ToArray and Encoding.GetBytes are methods for.
    ///
    /// ONE COPY, AND IT IS NOT AVOIDABLE HERE: the pointer borrows the
    /// core's allocation, and a byte[] aliasing it would outlive the
    /// release. The BLOB redemption pays nothing, and it is the route a
    /// font or an icon takes.
    public byte[] Bytes()
    {
        Alive("Bytes()");
        return Kaya.AssetBytes(handle);
    }

    /// The asset as a Stream: a MemoryStream over a copy of the bytes,
    /// seekable and non-writable. Entirely .NET's — the core knows
    /// nothing about it, and it stays valid after this Asset is
    /// disposed because it owns its own memory.
    public MemoryStream Open() => new MemoryStream(Bytes(), writable: false);

    /// The asset's byte count. Never 0 for a live asset: the core
    /// refuses a zero-byte asset at the open, because an empty blob
    /// sails through every lowering and is indistinguishable from a
    /// default.
    public int Length
    {
        get
        {
            Alive("Length");
            return Kaya.AssetLength(handle);
        }
    }

    /// THE BLOB REDEMPTION, used by the two consumers that take an
    /// Asset: it registers the core's own bytes into the pending table
    /// and answers the handle the next submit consumes. The bytes never
    /// enter .NET.
    ///
    /// INTERNAL, because the redemption is the binding's business and
    /// not the guest's: the BrandTypeface and AppIdentity overloads are
    /// the whole offer, and they are the same offer in all nine
    /// languages.
    internal ulong Blob()
    {
        Alive("a blob redemption");
        return Kaya.AssetBlob(handle);
    }

    /// Release the core's handle. Idempotent, and safe beside a `using`.
    public void Dispose()
    {
        ulong live = handle;
        handle = 0;
        if (live != 0) Kaya.AssetRelease(live);
        // The finalizer has nothing left to do, and an object on the
        // finalization queue costs a second GC generation to collect.
        GC.SuppressFinalize(this);
    }

    /// THE FORGETTING GUEST'S NET. A finalizer rather than a
    /// SafeHandle: a SafeHandle wraps an OS handle that the runtime
    /// knows how to close, and this is an index into a table inside the
    /// core. Release is idempotent, so this needs no bookkeeping of its
    /// own beyond not calling into the core with a zero.
    ~Asset()
    {
        if (handle != 0) Kaya.AssetRelease(handle);
    }

    void Alive(string what)
    {
        if (handle == 0)
            throw new ObjectDisposedException(nameof(Asset),
                $"kaya: {what} on a disposed asset (\"{Name}\") — the handle was " +
                "released, and the bytes it borrowed are the core's. Read inside " +
                "the `using`, or keep the bytes rather than the asset.");
    }

    public override string ToString() =>
        handle == 0 ? $"Asset(\"{Name}\", disposed)" : $"Asset(\"{Name}\", {Length} bytes)";
}

/// One representation, arriving — the sum a copy is the record of.
/// C# has records and pattern matching, so this is an abstract record
/// with one derived record per constructor and a `switch` expression is
/// the elimination.
///
/// YOU OFFER MANY AND YOU RECEIVE ONE, and the two shapes say so: a
/// record of five optional fields would invite a guest to check five
/// where four are structurally always empty.
abstract record Representation
{
    public sealed record Text(string Value) : Representation;

    public sealed record Html(string Value) : Representation;

    /// Encoded image bytes. WHAT COMES BACK MAY BE A RE-ENCODE — the
    /// hosts convert freely between image types — so compare what the
    /// image IS, never the bytes it arrived in.
    public sealed record Image(byte[] Bytes) : Representation;

    /// Files, plural INSIDE one representation — the same nesting
    /// text/uri-list and CF_HDROP already have. A pasted file is the
    /// picker's own capability arriving through a second door, so it
    /// opens with the call that already exists.
    public sealed record Files(List<PickedFile> Value) : Representation;

    /// An app-defined format, round-tripped verbatim.
    public sealed record Custom(string Id, byte[] Bytes) : Representation;

    /// Turn the decoder's kind-and-values into the sum, or null.
    ///
    /// EMPTY IS THE UNIVERSAL NO: null covers a denied prompt on iOS, an
    /// unfocused reader on Android or Wayland, an empty clipboard, and
    /// content in no representation this read accepted. The guest is not
    /// told which, because the platforms deliberately do not say.
    internal static Representation? From(KayaWire.ClipValues? clip)
    {
        if (clip == null) return null;
        string Str(int i) => i < clip.Values.Count && clip.Values[i] is string s ? s : "";
        byte[] Blob(int i) =>
            i < clip.Values.Count && clip.Values[i] is byte[] b ? b : Array.Empty<byte>();
        switch (clip.Kind)
        {
            case KayaWire.ClipText: return new Text(Str(0));
            case KayaWire.ClipHtml: return new Html(Str(0));
            case KayaWire.ClipImage: return new Image(Blob(0));
            case KayaWire.ClipCustom: return new Custom(Str(0), Blob(1));
            case KayaWire.ClipFiles:
                // The picker's own three-per-file grouping, so a guest
                // that decodes a dialog result decodes this with the
                // same loop.
                var files = new List<PickedFile>();
                for (int i = 0; i + 2 < clip.Values.Count; i += 3)
                {
                    long handle = clip.Values[i] is long h ? h : 0;
                    files.Add(new PickedFile((ulong)handle, Str(i + 1), Str(i + 2)));
                }
                return new Files(files);
            default: return null;
        }
    }
}

/// One signal the core put back: its id and its restored value.
readonly record struct UndoSignal(ulong Signal, object Value);

/// One field's restored text. A coarse episode restore is a
/// programmatic write, so nothing else would ever tell an app that
/// folds OnChange into its own model (docs/undo-plan.md D5).
///
/// TWO IDENTITIES IN ONE ENTRY, and they are the pair this binding
/// already hands to every template-node handler: an EMPTY Path means Id
/// is a live widget's id, and a non-empty one means Id is a TEMPLATE
/// NODE and Path is the stamped copy's key path, outermost first. A
/// collection row's field has no id an app could hold — its identity is
/// (node, keys), the same pair its clicks and its edits arrive under —
/// so the pair is the only way a payload can name one at all.
sealed class UndoText
{
    public ulong Id;
    /// The instance path: one key per enclosing For, empty for a live
    /// widget.
    public List<object> Path = new();
    public string Text = "";
}

/// One collection entry's restored state. State is null when the
/// restored state does not have this entry at all — the entry is gone,
/// which is what undoing an insert means.
sealed class UndoEntry
{
    public ulong Collection;
    /// The instance path: one key per enclosing For, empty at top level.
    public List<object> Path = new();
    public object Key;
    public (uint Variant, List<object> Fields)? State;
}

/// One collection instance's restored key order — position is the one
/// thing per-entry statements cannot carry, so it travels separately
/// and only for the instances a step actually reordered.
sealed class UndoOrder
{
    public ulong Collection;
    public List<object> Path = new();
    public List<object> Keys = new();
}

/// What an undo or a redo PUT BACK: the core-authoritative statement of
/// the restored state (docs/undo-plan.md D5).
///
/// A STATEMENT, NOT A REPLAY. Every member says what a thing now IS, so
/// a mirror that applies one twice is still correct and no binding
/// diffs anything of its own. The core owns the truth; the eight
/// bindings fold the same payload the way they already fold a rollback
/// journal, which is what keeps mirror drift to one implementation
/// instead of eight.
sealed class UndoDelta
{
    /// Signal id -> its restored value.
    public readonly List<UndoSignal> Signals = new();
    /// Widget id -> its restored text.
    public readonly List<UndoText> Texts = new();
    /// Collection entries, present or gone.
    public readonly List<UndoEntry> Entries = new();
    /// Instance orders, for the instances whose order the step changed.
    public readonly List<UndoOrder> Orders = new();
}

/// One step off the ledger, as the decoder hands it over: the group's
/// authored name — EMPTY for a typing episode, since kaya invents no
/// user-facing strings — and what the core put back.
sealed record UndoStep(string Label, UndoDelta Delta);

static class Kaya
{
    [StructLayout(LayoutKind.Sequential)]
    struct RingInfo
    {
        public IntPtr Data;
        public uint Capacity;
        public IntPtr Head;
        public IntPtr Tail;
    }

    [DllImport("kaya")]
    static extern int kaya_run();

    [DllImport("kaya")]
    static extern void kaya_occurrence_ring(out RingInfo info);

    [DllImport("kaya")]
    [return: MarshalAs(UnmanagedType.I1)]
    static extern bool kaya_wait_occurrences();

    [DllImport("kaya")]
    static extern void kaya_wake();

    /// Return the app thread from WaitOccurrences. Safe from any thread;
    /// the binding calls it from KayaApp.Post, and guests do not name it.
    public static void Wake() => kaya_wake();

    /// Block until there MAY be something to do: a record arrived, or
    /// another thread called Wake. False once the core has shut down.
    /// "May" is the honest word — a wake returns true with the ring
    /// still empty, and the caller re-checks both sources, which a
    /// drain-then-poll loop does anyway.
    public static bool WaitOccurrences() => kaya_wait_occurrences();

    [DllImport("kaya")]
    static extern void kaya_submit(byte[] records, nuint len);

    [DllImport("kaya")]
    static extern ulong kaya_blob_register(byte[] bytes, nuint len);

    [DllImport("kaya")]
    static extern IntPtr kaya_occurrence_blob(ulong handle, out nuint len);

    [DllImport("kaya")]
    static extern void kaya_occurrence_blob_release(ulong handle);

    /// Redeem an occurrence blob for its bytes, and release it. Called
    /// by the generated decoder, never by a guest.
    ///
    /// COPY THEN RELEASE, in that order: the pointer borrows core memory
    /// that the release frees. A blob arriving in an OCCURRENCE is a
    /// handle into a table with no boundary that retires one — unlike
    /// the apply channel's batch-local index, which the next batch
    /// supersedes — so the decoder is what has to let go of it, while
    /// decoding, before any handle can reach an app. Release is
    /// idempotent, so a dead handle costs nothing.
    public static byte[] OccurrenceBlob(ulong handle)
    {
        IntPtr data = kaya_occurrence_blob(handle, out nuint len);
        byte[] bytes = System.Array.Empty<byte>();
        if (data != IntPtr.Zero && len > 0)
        {
            bytes = new byte[(int)len];
            Marshal.Copy(data, bytes, 0, (int)len);
        }
        kaya_occurrence_blob_release(handle);
        return bytes;
    }

    [DllImport("kaya")]
    static extern int kaya_open_picked(
        ulong handle, uint mode, out long raw, out uint seekable);

    /// Redeem a picked handle for a real FileStream, plus whether it
    /// seeks. BLOCKS, and may block for a long time — a cloud provider
    /// can download the file before it answers — so call it from a
    /// thread you chose and post the result back (DESIGN.md, File
    /// dialogs).
    ///
    /// THE HANDLE BECOMES .NET'S. SafeFileHandle is constructed with
    /// ownsHandle: true, so disposing the stream closes it exactly once
    /// and the core keeps no claim. The core hands back the OS's own
    /// handle — a descriptor on POSIX, a HANDLE on Windows — precisely
    /// so each runtime converts it with its own file API rather than
    /// through a CRT descriptor only the minting CRT would accept, and
    /// SafeFileHandle takes both.
    public static (FileStream File, bool Seekable) OpenPicked(ulong handle, uint mode)
    {
        int rc = kaya_open_picked(handle, mode, out long raw, out uint seekable);
        if (rc != 0)
            throw new IOException($"kaya: opening the picked file failed (code {rc})");
        var access = mode switch
        {
            0 => FileAccess.Read,
            1 => FileAccess.Write,
            _ => FileAccess.ReadWrite,
        };
        var safe = new SafeFileHandle((IntPtr)raw, ownsHandle: true);
        return (new FileStream(safe, access), seekable != 0);
    }

    static RingInfo ring;

    /// On Windows, "kaya" resolves to kaya.dll via PATH. Elsewhere, point
    /// KAYA_LIB at the built library (e.g. target/debug/libkaya.dylib).
    /// Call once, before anything else.
    public static void Init()
    {
        NativeLibrary.SetDllImportResolver(typeof(Kaya).Assembly, (name, _, _) =>
        {
            string env = Environment.GetEnvironmentVariable("KAYA_LIB");
            if (name == "kaya" && env != null && NativeLibrary.TryLoad(env, out IntPtr handle))
                return handle;
            return IntPtr.Zero;
        });
        kaya_occurrence_ring(out ring);
    }

    /// Enter the core on the calling thread (which must be the process
    /// main thread); returns the exit code when the app ends.
    [DllImport("kaya")]
    static extern ulong kaya_spec_hash();

    public static int Run()
    {
        // The stale-artifact guard: this binding was generated from one
        // spec revision; the loaded library must speak the same one.
        if (kaya_spec_hash() != KayaWire.SpecHash)
            throw new InvalidOperationException(
                $"kaya: library speaks spec 0x{kaya_spec_hash():x16}, this binding was " +
                $"generated from 0x{KayaWire.SpecHash:x16} — rebuild the library or " +
                "regenerate bindings");
        return kaya_run();
    }

    /// Submit one transaction: the concatenation of packed records
    /// (KayaWire.Tx* results), applied atomically.
    public static void Submit(params byte[][] records)
    {
        int len = 0;
        foreach (byte[] r in records) len += r.Length;
        byte[] tx = new byte[len];
        int at = 0;
        foreach (byte[] r in records)
        {
            r.CopyTo(tx, at);
            at += r.Length;
        }
        kaya_submit(tx, (nuint)tx.Length);
    }

    /// Register bulk payload bytes (an encoded image) with the core:
    /// one copy into core-owned memory, returning the u64 handle the
    /// next submit from this guest consumes, referenced or not. The
    /// caller's bytes are free to drop the moment this returns.
    public static ulong RegisterBlob(byte[] data) =>
        kaya_blob_register(data, (nuint)data.Length);

    // THE ASSET TABLE: a file the guest's own BUILD put beside the
    // program, resolved and read by the CORE (docs/assets-plan.md). No
    // mode argument anywhere on this floor — assets are read-only
    // structurally — and no OS handle: kaya produced the bytes itself,
    // so PickedFile's necessity above does not arise here.
    [DllImport("kaya")]
    static extern ulong kaya_asset_open(byte[] name, nuint nameLen);

    [DllImport("kaya")]
    static extern IntPtr kaya_asset_bytes(ulong handle, out nuint len);

    [DllImport("kaya")]
    static extern nuint kaya_asset_len(ulong handle);

    [DllImport("kaya")]
    static extern ulong kaya_asset_blob(ulong handle);

    [DllImport("kaya")]
    static extern void kaya_asset_release(ulong handle);

    [DllImport("kaya")]
    static extern nuint kaya_asset_why_not(
        byte[] name, nuint nameLen, byte[] into, nuint cap);

    /// Open an asset by name; 0 is the MISS, and AssetMissSentence says why.
    ///
    /// ZERO RATHER THAN A RAISE FROM THE CORE, because a panic inside an
    /// extern "C" frame is an uncatchable process abort in every guest
    /// language. The core answers a value and the BINDING throws — Tx's
    /// Asset does it, carrying the core's sentence.
    ///
    /// The name travels as UTF-8 bytes with an explicit length rather
    /// than a NUL-terminated string, so every binding hands its own
    /// string type's bytes with no terminator to add.
    internal static ulong AssetOpen(string name) =>
        kaya_asset_open(Encoding.UTF8.GetBytes(name),
                        (nuint)Encoding.UTF8.GetByteCount(name));

    /// An open asset's bytes, copied out of core memory (the pointer
    /// borrows an allocation the release frees).
    internal static byte[] AssetBytes(ulong handle)
    {
        IntPtr data = kaya_asset_bytes(handle, out nuint len);
        byte[] bytes = System.Array.Empty<byte>();
        if (data != IntPtr.Zero && len > 0)
        {
            bytes = new byte[(int)len];
            Marshal.Copy(data, bytes, 0, (int)len);
        }
        return bytes;
    }

    internal static int AssetLength(ulong handle) => (int)kaya_asset_len(handle);

    /// THE BLOB REDEMPTION: the core's own bytes into the pending table,
    /// no copy through .NET. The handle the next submit consumes.
    internal static ulong AssetBlob(ulong handle) => kaya_asset_blob(handle);

    /// Idempotent, so a Dispose and a finalizer that follows it cost
    /// nothing between them.
    internal static void AssetRelease(ulong handle) => kaya_asset_release(handle);

    /// NAMED FOR THE CARRYING, not for the answering, and deliberately
    /// not AssetWhyNot. tools/check-diagnostics.sh reads any *WhyNot by
    /// that name alone and holds it to the rule that every branch must
    /// print what it measured — which is right, and which the function
    /// that EARNED the name already satisfies: asset_why_not in
    /// crates/kaya/src/assets.rs stats the root, lists what is there and
    /// reads the io error, and the gate audits it at answers=8,
    /// measured=8. This copies that sentence's bytes into a string. It
    /// observes nothing and could not print a second sentence if it
    /// tried, so calling it a why-not would put a diagnostic's name on a
    /// memcpy — and the other bindings in this slice name theirs the
    /// same way (Python's asset_miss_sentence, Go's assetMissSentence).
    ///
    /// The core's sentence for why an open would fail — empty when it
    /// would succeed.
    ///
    /// ASKED TWICE ON PURPOSE. The first call passes a null buffer to
    /// learn the length; the second fills a buffer of exactly that size.
    /// A fixed buffer would truncate the END of the sentence, which is
    /// where the census of what the package actually carries lives — the
    /// half that answers the reader's next question.
    ///
    /// THE PROSE IS THE CORE'S, whole and unedited: one author for the
    /// sentence, nine spellings of the raise.
    internal static string AssetMissSentence(string name)
    {
        byte[] raw = Encoding.UTF8.GetBytes(name);
        int needed = (int)kaya_asset_why_not(raw, (nuint)raw.Length, null, 0);
        if (needed == 0) return "";
        byte[] into = new byte[needed];
        int written = (int)kaya_asset_why_not(
            raw, (nuint)raw.Length, into, (nuint)needed);
        return Encoding.UTF8.GetString(into, 0, System.Math.Min(written, needed));
    }

    /// One value at `at`, advancing past it (header plus payload,
    /// padded to eight). A blob is redeemed and RELEASED here, exactly
    /// as the generated ParseClip does it: the pointer borrows core
    /// memory that the release frees, and an occurrence blob's handle
    /// has no batch boundary to retire it.
    static object ReadValue(byte[] rec, ref int at)
    {
        uint vtype = BitConverter.ToUInt32(rec, at);
        int vlen = (int)BitConverter.ToUInt32(rec, at + 4);
        object value = vtype switch
        {
            KayaWire.ValueBool => rec[at + 8] != 0,
            KayaWire.ValueI64 => BitConverter.ToInt64(rec, at + 8),
            KayaWire.ValueF64 => BitConverter.ToDouble(rec, at + 8),
            KayaWire.ValueBlob => OccurrenceBlob(BitConverter.ToUInt64(rec, at + 8)),
            _ => (object)Encoding.UTF8.GetString(rec, at + 8, vlen),
        };
        at += 8 + ((vlen + 7) & ~7);
        return value;
    }

    static long AsInt(object v) =>
        v is long n ? n
        : throw new InvalidOperationException(
            $"kaya: the undo delta wanted an integer, got {v?.GetType().Name ?? "null"}");

    /// Decode an `undone` / `redone` record — the two occurrence kinds
    /// the GENERATED parser cannot read.
    ///
    /// WHY THIS IS HAND-WRITTEN AND WHY IT IS IN FRONT. kaya-bindgen
    /// emits the record's constants and puts its kind in
    /// ParseOccurrence's accept list (both derive from the spec), but
    /// the body shape — four run counts, a label, then one flat value
    /// list read as four runs — is not one the generator models. Handed
    /// this record, ParseOccurrence reads the `signals` count as a key
    /// path length and the `entries`/`orders` counts as a value header,
    /// then walks off the end of the record. So the kind is checked
    /// BEFORE the generated parser is called, not after it fails.
    ///
    /// `id` is the WINDOW, because the ledger is per window (§3): Undo
    /// in one window has never meant "revert what happened in another".
    static bool ParseUndo(
        byte[] rec, out ushort kind, out ulong id, out List<object> keys, out object payload)
    {
        kind = BitConverter.ToUInt16(rec, 4);
        keys = new List<object>();
        id = BitConverter.ToUInt64(rec, 8);
        int signals = (int)BitConverter.ToUInt32(rec, 16);
        int texts = (int)BitConverter.ToUInt32(rec, 20);
        int entries = (int)BitConverter.ToUInt32(rec, 24);
        int orders = (int)BitConverter.ToUInt32(rec, 28);
        int at = 32;
        string label = ReadValue(rec, ref at) as string ?? "";
        int count = (int)BitConverter.ToUInt32(rec, at);
        at += 8; // the count and its reserved word
        var flat = new List<object>(count);
        for (int i = 0; i < count; i++)
            flat.Add(ReadValue(rec, ref at));

        var delta = new UndoDelta();
        int k = 0;
        List<object> Next(int n)
        {
            if (k + n > flat.Count)
                throw new InvalidOperationException("kaya: the undo delta is truncated");
            var run = flat.GetRange(k, n);
            k += n;
            return run;
        }
        for (int i = 0; i < signals; i++)
        {
            var pair = Next(2);
            delta.Signals.Add(new UndoSignal((ulong)AsInt(pair[0]), pair[1]));
        }
        // The last three runs are ARITY-FIRST groups — size counts
        // itself — so a reader needs no schema and a record it cannot
        // interpret still advances by exactly the right distance. Texts
        // joined them when a row's field had to be nameable: a fixed
        // (widget, text) pair had nowhere to put the path.
        for (int i = 0; i < texts; i++)
        {
            var head = Next(3);
            int size = (int)AsInt(head[0]);
            int pathLen = (int)AsInt(head[2]);
            // size counts the three head values too, so what is left is
            // the path and then exactly one string.
            var rest = Next(size - 3);
            delta.Texts.Add(new UndoText
            {
                Id = (ulong)AsInt(head[1]),
                Path = rest.GetRange(0, pathLen),
                Text = rest[pathLen] as string ?? "",
            });
        }
        for (int i = 0; i < entries; i++)
        {
            var head = Next(5);
            int size = (int)AsInt(head[0]);
            int pathLen = (int)AsInt(head[4]);
            var rest = Next(size - 5);
            var entry = new UndoEntry
            {
                Collection = (ulong)AsInt(head[1]),
                Path = rest.GetRange(0, pathLen),
                Key = rest[pathLen],
            };
            // Bit 0 of the flags says the entry EXISTS; clear means the
            // restored state does not have it.
            if ((AsInt(head[2]) & 1) != 0)
                entry.State = ((uint)AsInt(head[3]),
                    rest.GetRange(pathLen + 1, rest.Count - pathLen - 1));
            delta.Entries.Add(entry);
        }
        for (int i = 0; i < orders; i++)
        {
            var head = Next(3);
            int size = (int)AsInt(head[0]);
            int pathLen = (int)AsInt(head[2]);
            var rest = Next(size - 3);
            delta.Orders.Add(new UndoOrder
            {
                Collection = (ulong)AsInt(head[1]),
                Path = rest.GetRange(0, pathLen),
                Keys = rest.GetRange(pathLen, rest.Count - pathLen),
            });
        }
        if (k != flat.Count)
            throw new InvalidOperationException("kaya: the undo delta has trailing values");
        payload = new UndoStep(label, delta);
        return true;
    }

    /// Block for the next occurrence; false when the core has shut
    /// down. keys is empty when id is a widget id, else id is a
    /// template node id and keys is the stamped copy's key path,
    /// outermost first. payload carries the entry's new text (string)
    /// for OccKindTextChanged, the checkbox's new state (bool) for
    /// OccKindToggled, null for clicks.
    /// Read the next occurrence if one is ready, WITHOUT blocking;
    /// false means the ring is empty right now.
    ///
    /// Polling and waiting are separate calls, rather than one blocking
    /// NextOccurrence, because the app thread has a SECOND source of
    /// work: closures posted from other threads. A single blocking read
    /// would park inside C with no way back out to drain them.
    public static unsafe bool PollOccurrence(
        out ushort kind, out ulong id, out List<object> keys, out object payload)
    {
        uint* head = (uint*)ring.Head;
        uint* tail = (uint*)ring.Tail;
        byte* data = (byte*)ring.Data;
        uint mask = ring.Capacity - 1;

        uint h = Volatile.Read(ref *head);
        while (true)
        {
            uint t = Volatile.Read(ref *tail); // acquire: records below are visible
            if (h == t)
            {
                kind = 0;
                id = 0;
                keys = new List<object>();
                payload = null;
                return false; // nothing ready; the caller waits
            }
            byte* at = data + (h & mask);
            uint size = *(uint*)at;
            byte[] rec = new byte[size];
            Marshal.Copy((IntPtr)at, rec, 0, (int)size);
            ushort peek = BitConverter.ToUInt16(rec, 4);
            bool valid = peek == KayaWire.OccKindUndone || peek == KayaWire.OccKindRedone
                ? ParseUndo(rec, out kind, out id, out keys, out payload)
                : KayaWire.ParseOccurrence(rec, out kind, out id, out keys, out payload);
            h += size;
            Volatile.Write(ref *head, h); // release: hand the space back
            if (valid)
                return true;
        }
    }
}
